#include "db2eb1f3997853bc_creature_health.hpp"
namespace recovered_creature_health{
U level(U s,U subtract,Ports&p){U count=p.byte(s+0x89),total=0;if(!count)return 0;U owner=p.read(s+0x24),stats=p.read(owner+0xa74),classes=p.byte(stats+0x89);for(U i=0;i<count;++i){U v=0;if((i&255)<classes){U c=stats+(i&255)*40;v=p.byte(c+0xa8);U lost=subtract?p.byte(c+0xa9):0;v=v<lost?0:v-lost;}total+=v;}return total&255;}
U level_info(U s,U index,Ports&p){if(!p.read(s+0x6c))return 0;index&=255;if(static_cast<std::int32_t>(index)>=static_cast<std::int32_t>(p.read(s+0x2c)))return 0;return p.read(p.read(s+0x28)+index*4);}
U has_feat(U s,U id,Ports&p){id&=65535;U n=p.read(s+4),found=0;if(static_cast<std::int32_t>(n)>0){U a=p.read(s);for(U i=0;i<n;++i)if(p.half(a+2*i)==id)++found;}if(found)return 1;n=p.read(s+0x1c);if(static_cast<std::int32_t>(n)>0){U a=p.read(s+0x18);for(U i=0;i<n;++i)if(p.half(a+2*i)==id)++found;}return found?1:0;}
U current(U s,U base,Ports&p){return base==1?p.half(s+0xdc):p.read(s+0xe4)+p.read(s+0xdc);}
static U bonus(U self,U stats,Ports&p){if(has_feat(stats,0x7c,p))return 2;if(has_feat(p.read(self+0xa74),0x54,p))return 1;return 0;}
U maximum(U s,U feats,Ports&p){U total=0;if(p.read(p.read(s+0xa74)+0x6c)==1&&p.read(p.party()+0xf0)==0xffffffff){U i=0;if(level(p.read(s+0xa74),0,p)){do{U entry=level_info(p.read(s+0xa74),i,p);U stats=p.read(s+0xa74);int v=static_cast<std::int8_t>(p.byte(stats+0xee))+static_cast<int>(p.byte(entry+0x2b));if(v<1)v=1;if(feats)v+=static_cast<int>(bonus(s,stats,p));total+=static_cast<U>(v);++i;}while(i<level(p.read(s+0xa74),0,p));}return total&65535;}
 U extra=feats?bonus(s,p.read(s+0xa74),p):0;if(has_feat(p.read(s+0xa74),0x5f,p))extra+=2;U stats=p.read(s+0xa74);int mod=static_cast<std::int8_t>(p.byte(stats+0xee));U hp=p.half(s+0xe0);U value=level(stats,0,p)*static_cast<U>(mod)+static_cast<U>(static_cast<std::int16_t>(hp));U check=level(stats,0,p);if(static_cast<std::int32_t>(value)<static_cast<std::int32_t>(check)){stats=p.read(s+0xa74);U b=level(stats,0,p)*extra;return (b+level(stats,0,p))&65535;}stats=p.read(s+0xa74);hp=p.half(s+0xe0);mod=static_cast<std::int8_t>(p.byte(stats+0xee));return (level(stats,0,p)*(static_cast<U>(mod)+extra)+hp)&65535;}
U low(U s,Ports&p){if(p.read(s+0xac4))return 0;U hp=p.slot(s,0x9c,0,true);U max=p.slot(s,0x98,1,true);return p.ratio(hp,max);}
U base_dead(U s,Ports&p){if(p.slot(s,0x30,0,false)){U c=p.slot(s,0x30,0,false);if(p.read(c+0x9d4)){c=p.slot(s,0x30,0,false);return static_cast<std::int16_t>(p.slot(c,0x9c,0,true))<=-10;}}U c=p.slot(s,0x30,0,false);if(c)c=p.slot(s,0x30,0,false);else c=s;return static_cast<std::int16_t>(p.slot(c,0x9c,0,true))<=0;}
}
